<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import type { OnValueChange } from '../shared/types.js'; import { MenuRadioGroupState, setMenuRadioGroupContext } from './menu-context.svelte.js'; export interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> { children?: Snippet; value?: string | null; onValueChange?: OnValueChange<string, 'item-press'>; ref?: HTMLDivElement | null; } let { children, value = $bindable(null), onValueChange, ref = $bindable(null), ...rest }: Props = $props(); const radio = setMenuRadioGroupContext(new MenuRadioGroupState()); radio.select = (next, event) => { value = next; onValueChange?.(next, { reason: 'item-press', event }); }; $effect.pre(() => { radio.value = value; });</script>
<div bind:this={ref} {...rest} role="group">{@render children?.()}</div>
